type Join<Prefix extends string, Key extends string> = Prefix extends ""
  ? Key
  : `${Prefix}.${Key}`;

type Paths<T, Prefix extends string = ""> = T extends string
  ? Prefix
  : {
      [Key in keyof T & string]: Paths<T[Key], Join<Prefix, Key>>;
    }[keyof T & string];

export type MessageKey = Paths<typeof es>;

export function t(key: MessageKey): string {
  const value = key.split(".").reduce<unknown>((node, part) => {
    if (node && typeof node === "object" && part in node) {
      return (node as Record<string, unknown>)[part];
    }
    return undefined;
  }, es);

  if (typeof value !== "string") {
    throw new Error(`Clave de catálogo inexistente: ${key}`);
  }

  return value;
}
